import {renderPros004} from './pros004.mjs';
import {renderDailyResearch} from './sdv-daily.mjs';
import {displayTarget,researchAvailability} from './display.mjs';
import {filterRowsByScope, filterCandidateUniverse, resolveSportScope, validRequestedLegCount} from './scope.mjs';
import {loadSnapshot} from './snapshot.mjs';
import {filterResearchForecasts, summarizePmf, isHistoryForecast, groupForecastGrades, forecastGradeState, upcomingEmptyReasons} from './research.mjs';

let originalPairedRecord = null, activePairedGrades = null;
let renderOffers = null;
try {({originalPairedRecord,activePairedGrades} = await import('./paired-research.mjs'));} catch {}
try {({renderOffers} = await import('./offers.mjs'));} catch {}

const routes = [
  ['overview', 'Overview', '◫'], ['props', 'Props', '≡'], ['value', 'Value Research', '⇄'],
  ['builder', 'Paper Builder', '⊞'], ['performance', 'Performance', '▥'], ['sources', 'Source Health', '◉'], ['specials', 'Specials', '✧'],
];
const state = {snapshot: null, error: null, scope: {mode: 'SINGLE', sports: ['NBA']}, filters: {view: location.hash === '#/props/history' ? 'history' : 'upcoming', category: 'ALL', side: 'ALL', period: 'full_game', window: 'upcoming', venue: 'ALL', evidence: 'ALL'}, visibleForecasts: 28, visiblePros004: 28, visiblePaired: 28, visibleDaily: 28, builder: {legs: 6, mode: 'MIXED', checked: false}};
const main = document.querySelector('#main');
const escape = value => String(value).replace(/[&<>"']/g, char => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[char]));
const pill = (text, tone = '') => `<span class="pill ${tone}">${escape(text)}</span>`;
const datetime = value => value ? new Intl.DateTimeFormat('en-GB', {dateStyle: 'medium', timeStyle: 'short', timeZone: 'UTC'}).format(new Date(value)) + ' UTC' : 'Unknown';
const sports = () => state.snapshot?.sports || [];
const supported = () => sports().map(sport => sport.league);
const scopedSports = () => filterRowsByScope(sports(), state.scope, supported());
const allRows = key => sports().flatMap(sport => sport[key]);
const scopedRows = key => filterRowsByScope(allRows(key), state.scope, supported());
const scopedOffers = () => filterRowsByScope(state.snapshot?.offers?.offers || [],state.scope,supported());
const nbaSelected = () => resolveSportScope(state.scope,supported()).includes('NBA');
const pairedForecasts = (respectScope = true) => originalPairedRecord && (!respectScope || nbaSelected()) ? (state.snapshot?.pairedResearch?.forecasts || []).map(row=>({row,forecast:originalPairedRecord(row)})) : [];
const pairedPanel = (performance = false) => renderPairedResearch(state.snapshot?.pairedResearch,{performance});
const dailyForecasts = (respectScope = true) => !respectScope || nbaSelected() ? state.snapshot?.dailyResearch?.forecasts || [] : [];
const dailyPanel = (performance = false) => renderDailyResearch(state.snapshot?.dailyResearch,{view:state.filters.view,category:state.filters.category,window:state.filters.window,nbaSelected:nbaSelected() && (performance || ['ALL','RESEARCH'].includes(state.filters.evidence)),performance,limit:state.visibleDaily});
const reservedPanel = (performance = false) => renderPros004(state.snapshot?.pros004,{view:state.filters.view,category:state.filters.category,nbaSelected:nbaSelected() && (performance || ['ALL','RESEARCH'].includes(state.filters.evidence)),performance,limit:state.visiblePros004});
const number = value => Number(value).toLocaleString('en-GB', {maximumSignificantDigits: 5});
const percent = value => (100 * Number(value)).toLocaleString('en-GB', {maximumSignificantDigits: 4}) + '%';
const scopeLabel = () => {
  const selected = resolveSportScope(state.scope, supported());
  if (!selected.length) return 'No sports selected';
  return state.scope.mode === 'ALL' ? `All supported sports · ${selected.join(', ')}` : selected.join(' + ');
};
const empty = (title, text, icon = '◌') => `<div class="empty-state"><span class="empty-icon" aria-hidden="true">${icon}</span><h3>${title}</h3><p>${text}</p></div>`;
const pageHeading = (eyebrow, title, description, extra = '') => `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${extra}</div>`;
const panel = (title, content, sub = '', extra = '') => `<section class="panel"><div class="panel-heading"><div><h2>${title}</h2>${sub ? `<p>${sub}</p>` : ''}</div>${extra}</div>${content}</section>`;

function publicationStatus() {
  if (state.error) return `<div class="notice error" role="alert"><strong>Published snapshot unavailable</strong><p>${escape(state.error)} No opportunities or paper candidates can be shown. Refresh to retry the published files.</p></div>`;
  const errors = state.snapshot?.errors || [];
  const missing = Object.entries(state.snapshot?.manifest.errors || {}).filter(([league]) => !state.snapshot.manifest.sports.some(reference => reference.league === league));
  const displayError = state.snapshot?.displayError;
  const displayNotice = displayError ? `<div class="notice warning"><strong>${state.snapshot?.display ? 'Earlier verified display metadata retained' : 'Readable names unavailable'}</strong><p>${escape(displayError)} ${state.snapshot?.display ? `Names verified ${datetime(state.snapshot.display.catalog.verified_at)}; metadata assembled ${datetime(state.snapshot.display.generated_at)}. The failed update did not refresh these clocks.` : 'Forecast records remain visible with their original source IDs.'}</p></div>` : '';
  const channelNotice = [['pros004Error','Reserved study'],['pairedResearchError','Paired operational research'],['dailyResearchError','Daily-snapshot research'],['offersError','Offer publication']].map(([key,label])=>state.snapshot?.[key] ? `<div class="notice warning"><strong>${label} unavailable</strong><p>${escape(state.snapshot[key])} Other verified publication channels remain available; no missing record is counted as issued.</p></div>` : '').join('');
  const catalogNotice = (state.snapshot?.manifest.sports || []).filter(reference=>reference.error && !reference.retained).map(reference=>`<div class="notice error" role="alert"><strong>${escape(reference.league)} research records unavailable</strong><p>${escape(reference.error)} The category catalog and independently verified offers can remain available.</p></div>`).join('');
  return displayNotice + channelNotice + catalogNotice + errors.map(error => `<div class="notice error" role="alert"><strong>${escape(error.league)} snapshot unavailable</strong><p>${escape(error.message)} Other valid sport snapshots remain visible.</p></div>`).join('') + missing.map(([league, message]) => `<div class="notice error" role="alert"><strong>${escape(league)} update unavailable</strong><p>${escape(message)} No valid prior snapshot is available for this sport.</p></div>`).join('') + (state.snapshot?.manifest.sports || []).filter(reference => reference.retained).map(reference => `<div class="notice warning"><strong>${escape(reference.league)} retains an earlier snapshot</strong><p>Generated ${datetime(reference.generated_at)}. ${escape(reference.error || 'The new observation was not published.')} This publication time does not refresh its inputs.</p></div>`).join('');
}

function snapshotNote() {
  const manifest = state.snapshot?.manifest;
  return `<div class="snapshot-note"><span class="status-dot"></span>${manifest ? `Publication ${datetime(manifest.published_at)} <span class="note-divider">/</span> Build <code title="${escape(manifest.build_commit)}">${manifest.build_commit.slice(0, 10)}</code>` : 'No verified publication loaded'}<span class="snapshot-qualifier">Publication time is not a quote observation time.</span></div>`;
}

function scopeControl() {
  return `<fieldset class="scope-control"><legend>Sport scope</legend><div class="segmented" role="group" aria-label="Sport selection mode">${[['SINGLE', 'One sport'], ['SELECTED', 'Selected sports'], ['ALL', 'All supported']].map(([value, label]) => `<button type="button" class="${state.scope.mode === value ? 'active' : ''}" data-scope="${value}" aria-pressed="${state.scope.mode === value}">${label}</button>`).join('')}</div><div class="sport-choices">${supported().length ? supported().map(league => `<label class="sport-choice"><input type="${state.scope.mode === 'SINGLE' ? 'radio' : 'checkbox'}" name="sport" value="${escape(league)}" ${resolveSportScope(state.scope, supported()).includes(league) ? 'checked' : ''} ${state.scope.mode === 'ALL' ? 'disabled' : ''}><span>${escape(league)}</span><span class="mini-label">Research coverage</span></label>`).join('') : '<span class="muted">No sport snapshot available.</span>'}</div><p class="control-help">Available choices follow published coverage. “All” currently means ${supported().join(', ') || 'no available sports'}. Coverage does not qualify forecasts or products.</p></fieldset>`;
}

function categoryGrid(markets) {
  if (!markets.length) return empty('Category snapshot unavailable', 'No validated inventory has loaded. Research scope remains defined in the repository.');
  return `<div class="category-grid">${markets.filter(market => market.requested).map(market => `<div class="category-card"><span class="category-code">${escape(market.code)}</span><span>${escape(market.name.replace(' indicator', ''))}</span><span class="category-status">Research scope</span></div>`).join('')}</div>`;
}

function researchStatus(rows = scopedSports()) {
  const count = researchAvailability(rows), status = state.snapshot?.display?.status;
  const paired = rows.some(sport=>sport.league==='NBA') ? pairedForecasts(false) : [];
  const daily = rows.some(sport=>sport.league==='NBA') ? dailyForecasts(false) : [];
  count.upcoming += paired.filter(({row,forecast})=>row.admission.eligible && Date.parse(forecast.event_starts_at)>Date.now()).length;
  count.history += paired.filter(({row,forecast})=>!row.admission.eligible || Date.parse(forecast.event_starts_at)<=Date.now()).length;
  count.upcoming += daily.filter(row=>row.admission.eligible && Date.parse(row.body.event_starts_at)>Date.now()).length;
  count.history += daily.filter(row=>row.body.mode==='PROSPECTIVE_RESEARCH' && (!row.admission.eligible || Date.parse(row.body.event_starts_at)<=Date.now())).length;
  count.offers = (state.snapshot?.offers?.offers || []).filter(offer=>rows.some(sport=>sport.league===offer.league)).length;
  const capturedTimes=[...daily.filter(row=>row.admission.eligible).map(row=>row.body.issued_at),...paired.filter(({row})=>row.admission.eligible).map(({forecast})=>forecast.issued_at),...rows.flatMap(sport=>sport.forecasts).filter(f=>f.evidence_lane==='REAL_TIME_CAPTURED').map(f=>f.issued_at)].filter(Boolean).sort();
  const issuedAt=capturedTimes.at(-1);
  const dailyInputs=rows.some(sport=>sport.league==='NBA') ? state.snapshot?.dailyResearch?.inputs || [] : [];
  const dailyRetrieved=dailyInputs.flatMap(input=>input.sources.map(source=>source.retrieved_at)).sort().at(-1);
  const dailyPreparation=dailyInputs.some(input=>input.mode==='DEVELOPMENT_ONLY');
  const lastOffer=(state.snapshot?.offers?.offers || []).filter(offer=>rows.some(sport=>sport.league===offer.league)).map(offer=>offer.observed_at).sort().at(-1);
  return `<section class="panel research-availability" aria-label="Independent research, offer and ticket status"><div class="availability-grid"><div><h2>Research forecasts</h2><strong>${count.upcoming} upcoming · ${count.history} in History</strong><p>Price-independent distributions. Historical reconstruction is labelled separately from genuine pregame issuance.</p>${count.history ? '<a class="text-link history-shortcut" href="#/props/history">Explore research History <span aria-hidden="true">→</span></a>' : ''}</div><div><h2>Offers</h2><strong>${count.offers} published player contracts</strong><p>${count.offers ? 'Offer evidence remains separate from forecast and ticket qualification.' : 'No complete player contract with reviewed source permission has been admitted to this publication. An admitted offer-only record may show “price unavailable”; quotes, value estimates and tickets have separate checks.'}</p></div><div><h2>Paper tickets</h2><strong>${count.tickets} qualified · NO_ACTION</strong><p>Forecast availability does not establish venue terms, settlement rules or ticket qualification.</p></div></div><dl class="publication-clocks"><div><dt>Site publication</dt><dd>${datetime(state.snapshot?.manifest.published_at)}</dd></div><div><dt>Last retained NBA forecast-input preparation</dt><dd>${status?.latest_retained_input_capture ? `${datetime(status.latest_retained_input_capture.observed_at)}<span class="cell-sub">Preparation only; pregame timeliness is not established.</span>` : 'Unavailable in this snapshot'}</dd></div><div><dt>Last paired operational source capture</dt><dd>${state.snapshot?.pairedResearch?.clocks.last_source_capture_at ? datetime(state.snapshot.pairedResearch.clocks.last_source_capture_at) : 'None recorded in the paired publication'}<span class="cell-sub">A source capture alone is not timely forecast issuance.</span></dd></div><div><dt>Last daily-snapshot asset retrieval</dt><dd>${dailyRetrieved ? datetime(dailyRetrieved) : 'No daily-source asset retrieval in this scope'}<span class="cell-sub">${dailyPreparation ? 'Development-only preparation; no genuine issuance.' : 'Retrieval is distinct from publisher update, unknown upstream observation and actual issuance.'}</span></dd></div><div><dt>Last admitted offer observation</dt><dd>${lastOffer ? datetime(lastOffer) : 'No admitted offer observation in this scope'}<span class="cell-sub">Publication does not refresh line, price or market status.</span></dd></div><div><dt>Last genuine pregame issuance</dt><dd>${issuedAt ? datetime(issuedAt) : 'None recorded in the published forecasts'}</dd></div></dl><p class="control-help">Publishing the site does not refresh source captures, issue forecasts or settle tickets. Name verification has its own source observation dates.</p></section>`;
}

function renderPairedResearch(asset,{performance=false}={}) {
  if (!asset || !nbaSelected() || !originalPairedRecord || !activePairedGrades || !performance && !['ALL','RESEARCH'].includes(state.filters.evidence)) return '';
  const all=pairedForecasts(), grades=new Map(activePairedGrades(asset).map(row=>{const grade=originalPairedRecord(row);return [grade.forecast_id,{row,grade}];}));
  const limit=state.visiblePaired;
  const missing = (asset.missing_peers || []).map(peer=>{const label=all.find(({forecast})=>forecast.player_id===peer.player_id)?.forecast.player_label || `Player ${peer.player_id} (name unavailable)`;return `${label} / ${peer.model_key}`;});
  const header=`<div class="notice"><strong>One-event paired operational research · ${escape(asset.status.replaceAll('_',' '))}</strong><p>${escape(asset.reason)} This delivery exercise is separate from the reserved comparative study. Individual statistical grades are separate from financial settlement; qualification remains unavailable.</p>${missing.length?`<p>Missing peers: ${missing.map(escape).join('; ')}. No replacement or late completion is implied.</p>`:''}</div>`;
  if (performance) {
    const rows=all.filter(({forecast})=>grades.has(forecast.forecast_id));
    const receipts=rows.slice(0,limit).map(({row,forecast})=>{const {grade}=grades.get(forecast.forecast_id);return `<article class="grade-receipt"><h3>${escape(forecast.player_label)} · ${escape(forecast.model_key)}</h3><p>${escape(grade.status.replaceAll('_',' '))} · ${datetime(grade.graded_at)} · Financial settlement NOT_EVALUATED. ${row.admission.eligible?'Timely pregame delivery verified.':'Retained original is not eligible for timely prospective delivery.'}</p><p>Event ${escape(forecast.event_id)} · ${datetime(forecast.event_starts_at)}. Original <code class="break-code">${escape(row.original_id)}</code></p>${grade.status==='SCORED'?`<div class="table-wrap"><table><caption>Individual statistical scores; no paired aggregate evaluation</caption><thead><tr><th>Category</th><th>Observed</th><th>CRPS / RPS</th><th>Log loss</th></tr></thead><tbody>${grade.categories.filter(c=>state.filters.category==='ALL'||c.code===state.filters.category).map(c=>`<tr><th>${escape(c.code)}</th><td>${escape(c.observed)}</td><td>${number(c.crps)}</td><td>${c.log_loss_status==='ZERO_SUPPORT'?'∞ · ZERO_SUPPORT':number(c.log_loss)}</td></tr>`).join('')}</tbody></table></div>`:'<p>DNP and unresolved outcomes receive no statistical category scores.</p>'}</article>`;}).join('');
    return panel('Paired operational forecast grades',header+(receipts||empty('Statistical outcomes pending','No verified completed outcome and statistical grade has been published for this operational pilot. No missing outcome becomes zero or a loss.')),`${asset.counts.grades} individual grades · ${asset.counts.pending_grades} pending. No comparative aggregate is computed.`);
  }
  const history=state.filters.view==='history',now=Date.now(),horizon=state.filters.window==='24h'?86400000:state.filters.window==='7d'?7*86400000:Infinity;
  const records=all.filter(({row,forecast})=>history ? !row.admission.eligible || Date.parse(forecast.event_starts_at)<=now : row.admission.eligible && Date.parse(forecast.event_starts_at)>now && Date.parse(forecast.event_starts_at)<=now+horizon);
  const categories=records.flatMap(({row,forecast})=>forecast.categories.filter(c=>state.filters.category==='ALL'||c.code===state.filters.category).map(category=>({row,forecast,category})));
  const cards=categories.slice(0,limit).map(({row,forecast,category})=>{
    const summary=summarizePmf(category.pmf),grade=grades.get(forecast.forecast_id)?.grade;
    const label=displayTarget({...forecast,league:'NBA',id_namespace:forecast.id_namespace || 'espn'},state.snapshot?.display);
    return `<article class="forecast-card paired-forecast-card" data-market="${escape(category.code)}"><div class="forecast-card-heading"><div><span class="eyebrow">NBA · ${escape(category.code)} · ${escape(forecast.model_key)}</span><h3>${escape(forecast.player_label)}</h3><p>${escape(label.matchup)}<br>${datetime(forecast.event_starts_at)}</p></div>${pill(row.admission.eligible?'Genuine pregame research':'Retained, not eligible','research-pill')}</div><div class="forecast-metrics"><div><span>Mean</span><strong>${number(summary.mean)}</strong></div><div><span>Central 80% interval</span><strong>${summary.interval80[0]}–${summary.interval80[1]}</strong></div><div><span>Zero probability</span><strong>${percent(summary.zero)}</strong></div></div>${pmfChart(category)}<p>Conditional on appearance · Full game including overtime. Statistical grade: ${grade?escape(grade.status.replaceAll('_',' ')):'pending'}.</p><p>Research forecast · Qualification unavailable · No financial settlement.</p><details><summary>Original distribution and issuance evidence</summary><dl class="forecast-provenance">${[['Protocol',asset.protocol_id],['Player / event IDs',`${forecast.player_id} / ${forecast.event_id}`],['Historical team / opponent IDs',`${forecast.team_id} / ${forecast.opponent_id}`],['Model',forecast.model_version],['Producer',forecast.producer_version],['Input cutoff',forecast.cutoff_at],['Generation completed',forecast.generation_completed_at],['Original issue time',forecast.issued_at],['Local persistence completed',row.admission.local_persistence_completed_at || 'Unacknowledged'],['Remote checkpoint completed',row.admission.remote_checkpoint_completed_at || 'Unacknowledged'],['Independent final readback',row.admission.final_recovery_completed_at || 'Unacknowledged'],['Original forecast ID',row.original_id]].map(([key,value])=>`<div><dt>${key}</dt><dd><code>${escape(value)}</code></dd></div>`).join('')}</dl>${row.admission.reasons.length?`<p>${row.admission.reasons.map(escape).join(' ')}</p>`:''}<div class="table-wrap"><table><caption>Exact ${escape(category.code)} original research PMF</caption><thead><tr><th>Outcome</th><th>Probability</th></tr></thead><tbody>${category.pmf.map(atom=>`<tr><td>${atom.value}</td><td><code>${escape(atom.probability)}</code></td></tr>`).join('')}</tbody></table></div></details></article>`;
  }).join('');
  const emptyState=empty(history?'No paired operational records in History':'No upcoming paired operational forecasts',escape(asset.reason));
  const more=categories.length>limit?`<button class="button dark load-more" id="more-paired-research">Show next ${Math.min(28,categories.length-limit)} paired category forecasts</button>`:'';
  return panel('Paired operational research',header+(cards?`<div class="forecast-grid">${cards}</div>`:emptyState)+more,`${records.length} original forecasts in this view · ${asset.counts.missing_peers} missing peers. Original probabilities and clocks are retained.`);
}

function overview() {
  const nba = sports().find(sport => sport.league === 'NBA');
  const marketCount = nba?.markets.filter(market => market.requested).length;
  return `<section class="hero"><div class="hero-content"><div class="eyebrow"><span class="status-dot"></span> THE LAB IS TAKING SHAPE</div><h1>Better questions.<br><em>Stronger evidence.</em></h1><p>A shared home for player-outcome research, exact offers and carefully evaluated paper decisions. Starting with the NBA.</p><div class="hero-actions"><a class="button primary" href="#/props/history">Explore historical research <span aria-hidden="true">↗</span></a><a class="text-link light" href="#/sources">See source status <span aria-hidden="true">→</span></a></div></div><div class="hero-aside" aria-label="Research process"><div class="lab-orbit" aria-hidden="true"><div class="orbit-ring ring-one"></div><div class="orbit-ring ring-two"></div><div class="orbit-ring ring-three"></div><span class="orbit-center">N<span>THE LAB</span></span><span class="orbit-dot dot-one"></span><span class="orbit-dot dot-two"></span><span class="orbit-dot dot-three"></span></div><p>OBSERVE <span>→</span> FORECAST <span>→</span> EVALUATE</p></div></section>
  <div class="summary-grid"><div class="summary-card"><span class="summary-label">INITIAL COVERAGE</span><strong>NBA<span class="tiny-tag">Research</span></strong><p>Other sports require independent admission.</p></div><div class="summary-card"><span class="summary-label">REQUIRED CATEGORIES</span><strong>${marketCount ?? '—'}<span class="summary-unit">in development scope</span></strong><p>One coherent joint-outcome foundation.</p></div><div class="summary-card"><span class="summary-label">PAPER DECISION</span><strong class="no-action">NO_ACTION</strong><p>No qualified ticket is available.</p></div></div>
  ${researchStatus(sports())}
  ${panel('A full-category foundation', categoryGrid(nba?.markets || []), 'Every requested NBA category is in scope. Each must earn its own evidence.', '<a class="text-link" href="#/props">View inventory <span aria-hidden="true">→</span></a>')}
  <div class="two-col">${panel('Where the evidence stands', `<div class="stage-list">${[['01', 'Source & identity', 'Audit actual rows, capture clocks and permitted use.'], ['02', 'Forecast research', 'Evaluate all categories under shared chronological definitions.'], ['03', 'Paper qualification', 'Require supported quotes, terms and joint outcomes.']].map(([number, title, text]) => `<div class="stage-row"><span>${number}</span><div><h3>${title}</h3><p>${text}</p></div>${pill('In progress', 'neutral')}</div>`).join('')}</div>`)}${panel('Research is not a result', `<p class="body-copy">An inventory, a software check and a statistical evaluation establish different things. This publication makes no validated forecast, profitability or product qualification claim.</p><div class="callout"><strong>No invented picks.</strong><p>Offers, probabilities and outcomes appear only when supported by retained evidence.</p></div><a class="text-link" href="#/performance">Understand the scorecards <span aria-hidden="true">→</span></a>`)}</div>`;
}

function selectControl(label, key, options, value) {
  return `<label class="filter-label">${label}<select data-filter="${key}">${options.map(([option, name]) => `<option value="${escape(option)}" ${value === option ? 'selected' : ''}>${escape(name)}</option>`).join('')}</select></label>`;
}

function pmfChart(category) {
  const pmf = category.pmf, max = Math.max(...pmf.map(item => Number(item.probability)));
  const minimum = pmf[0].value, span = Math.max(1, pmf.at(-1).value - minimum + 1), width = Math.min(30, 270 / span * 0.8);
  return `<svg class="pmf-chart" viewBox="0 0 300 88" role="img" aria-label="${escape(category.code)} research probability mass distribution; relative heights show probability"><line x1="10" y1="72" x2="290" y2="72" stroke="#dbe4d2"/>${pmf.map(item => {const height = Number(item.probability) / max * 62, x = 10 + (item.value - minimum + 0.5) / span * 280; return `<rect x="${x - width / 2}" y="${72 - height}" width="${width}" height="${height}" rx="1.5" fill="#789b51"><title>${item.value}: ${percent(item.probability)}</title></rect>`;}).join('')}<text x="10" y="85">${minimum}</text><text x="290" y="85" text-anchor="end">${pmf.at(-1).value}</text></svg>`;
}

function forecastCard({forecast, category}) {
  const summary = summarizePmf(category.pmf);
  const display = displayTarget(forecast,state.snapshot?.display);
  const event = sports().flatMap(sport => sport.events).find(event => event.event_id === forecast.event_id && event.league === forecast.league);
  const reconstructed = forecast.evidence_lane === 'RECONSTRUCTED_RESEARCH';
  const grade = forecastGradeState(forecast, scopedRows('performance'));
  const gradeLabel = grade.pending ? 'Statistical grade: pending' : `Statistical grades: ${grade.statuses.map(status => status.replaceAll('_', ' ')).join(', ')}`;
  const metadata = [['Original record label', forecast.player_label], ['Display name basis', display.nameBasis], ['Display sources', display.sourceIds.join(', ') || 'Unavailable; original identity retained'], ['Event team', display.teamName], ['Event opponent', display.opponentName], ['Event ID', forecast.event_id], ['Player ID', forecast.player_id], ['Team / opponent IDs', `${forecast.team_id} / ${forecast.opponent_id}`], ['Model version', forecast.model_version], ['Model commit', forecast.model_commit], ['Model code SHA-256', forecast.model_code_sha256], ['Input SHA-256', forecast.input_sha256], ['Joint outcome SHA-256', forecast.joint_sha256], ['Trained through', forecast.trained_through], ['History freeze', forecast.history_freeze], ['Input cutoff (T−90)', forecast.cutoff_at], ['Actual issued time', forecast.issued_at], ['Forecast ID', forecast.forecast_id]];
  if (forecast.prospective) {
    const details = forecast.prospective;
    metadata.push(...[['Pregame producer', details.producer_version], ['Event version', details.event_version], ['Selected cohort SHA-256', details.selection_sha256], ['Input capture record', details.source_pack_record_id], ['Source-pack SHA-256', details.source_pack_sha256], ['Source observation range', `${details.source_observed_min_at} – ${details.source_observed_max_at}`], ['Actual normalized import', details.imported_at], ['Generation started', details.generation_started_at], ['Generation completed', details.generation_completed_at], ['Historical rows', String(details.history_rows)], ['Latest historical event', details.history_latest_event_at], ['Base model', details.base_model_version], ['Base model code SHA-256', details.base_model_code_sha256]]);
  }
  return `<article class="forecast-card" data-market="${escape(category.code)}"><div class="forecast-card-heading"><div><span class="eyebrow">${escape(forecast.league)} · ${escape(category.code)}${category.code === 'PA' ? ' · OPTIONAL' : ''} · FULL GAME</span><h3>${escape(display.playerName)}</h3><p class="forecast-context">${escape(display.teamName)} · opponent ${escape(display.opponentName)}</p><p>${escape(display.matchup)}<br><time datetime="${escape(forecast.event_starts_at)}">${datetime(forecast.event_starts_at)}</time></p></div>${pill(reconstructed ? 'Historical reconstruction' : 'Captured research', 'research-pill')}</div><div class="forecast-metrics"><div><span>Mean</span><strong>${number(summary.mean)}</strong></div><div><span>Central 80% interval</span><strong>${summary.interval80[0]}–${summary.interval80[1]}</strong></div><div><span>Zero probability</span><strong>${percent(summary.zero)}</strong></div></div>${pmfChart(category)}<div class="forecast-tail"><span>Finite support ${summary.support[0]}–${summary.support[1]}</span><span>P(X &gt; ${summary.upper95}) = ${percent(summary.tail)}</span></div><p class="forecast-semantics">Conditional on appearance · Includes overtime · ${escape(category.units.replaceAll('_', ' '))}. DNP is a separate state.</p><div class="forecast-statuses">${pill('Forecast: research', 'neutral')}${pill('Price: unavailable', 'neutral')}${pill('Qualification: unavailable', 'neutral')}${pill(gradeLabel, 'neutral')}</div><details class="forecast-details"><summary>Distribution &amp; provenance</summary><p>${reconstructed ? 'Reconstructed input timing is an assumption for historical research. The actual issue clock is after the event; this is not a pregame receipt.' : 'Captured inputs precede the declared issue clock. This research record does not qualify a betting product.'}</p><p><strong>${escape(forecast.evidence_lane)}</strong> · ${escape(forecast.availability_basis)} · ${escape(forecast.joint_method)}</p><p>Finite empirical support, without smoothing or unseen tail mass. The largest observed support value is not a physical maximum. Tail probability above the central 95% interval endpoint is descriptive.</p><dl class="forecast-provenance">${metadata.map(([label, value]) => `<div><dt>${label}</dt><dd><code>${escape(value)}</code></dd></div>`).join('')}</dl><div class="table-wrap"><table class="pmf-table"><caption>Exact ${escape(category.code)} research PMF</caption><thead><tr><th scope="col">Outcome</th><th scope="col">Probability</th></tr></thead><tbody>${category.pmf.map(item => `<tr><th scope="row">${item.value}</th><td><code>${escape(item.probability)}</code></td></tr>`).join('')}</tbody></table></div></details></article>`;
}

function forecastBoard(rows) {
  if (!resolveSportScope(state.scope, supported()).length) return empty('No sport selected', 'Choose a published sport or group. The research universe remains empty until you select coverage.');
  if (state.filters.view === 'upcoming' && !rows.length && (pairedForecasts().some(({row,forecast})=>row.admission.eligible && Date.parse(forecast.event_starts_at)>Date.now()) || dailyForecasts().some(row=>row.admission.eligible && Date.parse(row.body.event_starts_at)>Date.now()))) return empty('Reference forecast view', 'The admitted pregame research forecasts appear below. Their delivery is independent of prices, ticket qualification and the inactive reserved comparison.');
  if (state.filters.view === 'upcoming' && !rows.length) {
    const reasons = upcomingEmptyReasons(scopedSports());
    const historyCount = scopedRows('forecasts').filter(row => isHistoryForecast(row)).length;
    return empty('No upcoming research forecasts', 'No admitted pregame research forecast matches this future view. Prices and ticket qualification are separate; past-event research remains available in History.') + `<details class="availability-details"><summary>Research timing details</summary><ul class="availability-reasons">${[...new Set(reasons)].map(reason => `<li>${escape(reason)}</li>`).join('')}</ul></details>${historyCount ? `<a class="button dark history-shortcut" href="#/props/history">Explore ${historyCount} forecast records in History <span aria-hidden="true">→</span></a>` : ''}`;
  }
  if (!rows.length) return empty('No History records match this selection', 'Change the category or sport scope to inspect past-event forecasts and reconstructed research. Each record retains its own evidence lane.');
  return `<div class="notice historical-notice"><strong>${state.filters.view === 'history' ? 'Past-event forecasts and reconstructed research' : 'Captured research, not a qualified paper pick'}</strong><p>Event dates, input cutoffs, actual issue times and each evidence lane are preserved. Passing an event start does not establish completion. Forecasts remain unvalidated with no admitted price or ticket qualification.</p></div><div class="forecast-grid">${rows.slice(0, state.visibleForecasts).map(forecastCard).join('')}</div>${rows.length > state.visibleForecasts ? `<button class="button dark load-more" id="more-forecasts">Show next ${Math.min(28, rows.length - state.visibleForecasts)} category forecasts</button>` : ''}`;
}

function props() {
  const markets = scopedSports().flatMap(sport => sport.markets);
  const categories = [...new Map(markets.map(market => [market.code, market])).values()];
  const now = Date.now();
  const rows = scopedOffers().filter(offer => {
    const start = Date.parse(offer.event_starts_at), upcoming = start > now;
    const viewMatch = state.filters.view === 'history' ? !upcoming : upcoming;
    const horizon = state.filters.window === '24h' ? 86400000 : state.filters.window === '7d' ? 7 * 86400000 : Infinity;
    return viewMatch && (state.filters.view === 'history' || start <= now + horizon)
      && (state.filters.category === 'ALL' || offer.stat === state.filters.category)
      && (state.filters.side === 'ALL' || offer.side.toUpperCase() === state.filters.side)
      && (state.filters.venue === 'ALL' || offer.venue === state.filters.venue)
      && offer.period === state.filters.period && ['ALL','OFFER_ONLY'].includes(state.filters.evidence);
  });
  const venues = [...new Set(scopedOffers().map(offer=>offer.venue))].sort();
  let forecasts = filterResearchForecasts(scopedRows('forecasts'), state.filters);
  if (!['ALL', 'RESEARCH'].includes(state.filters.evidence)) forecasts = [];
  return pageHeading('THE RESEARCH BOARD', 'Props', 'Inspect price-independent research distributions and exact offers within your selected sport scope.', pill('Research · qualification unavailable', 'neutral')) + researchStatus() + `<section class="panel filter-panel">${scopeControl()}<div class="filter-grid">${selectControl('Research view', 'view', [['upcoming', 'Upcoming · captured research'], ['history', 'History · past events & reconstructions']], state.filters.view)}${selectControl('Category', 'category', [['ALL', 'All categories'], ...categories.map(market => [market.code, `${market.code} · ${market.name.replace(' indicator', '')}`])], state.filters.category)}${selectControl('Event window', 'window', [['upcoming', 'All events in this view'], ['24h', 'Next 24 hours · upcoming only'], ['7d', 'Next 7 days · upcoming only']], state.filters.window)}${selectControl('Period', 'period', [['full_game', 'Full game · includes overtime']], state.filters.period)}${selectControl('Offer side', 'side', [['ALL', 'All sides'], ['OVER', 'Over'], ['UNDER', 'Under']], state.filters.side)}${selectControl('Offer venue', 'venue', [['ALL', 'All observed venues'], ...venues.map(venue=>[venue,venue])], state.filters.venue)}${selectControl('Evidence', 'evidence', [['ALL', 'All evidence states'], ['OFFER_ONLY', 'Offer only'], ['RESEARCH', 'Research forecast'], ['EVALUATED', 'Evaluated forecast'], ['PRICED', 'Priced paper candidate']], state.filters.evidence)}</div><p class="control-help">Side and venue apply to offers. Forecast distributions remain price-independent and have no over/under side until matched to an exact line.</p></section>` + panel('Research forecasts', forecastBoard(forecasts), `${escape(scopeLabel())} · ${forecasts.length} category distributions in this view · ${Math.min(state.visibleForecasts, forecasts.length)} shown`, pill(state.filters.view === 'history' ? 'History' : 'Upcoming only', 'research-pill')) + dailyPanel() + pairedPanel() + reservedPanel() + panel('Published offers', rows.length && typeof renderOffers === 'function' ? renderOffers(state.snapshot.offers,{offers:rows,forecasts:[...scopedRows('forecasts'),...pairedForecasts().filter(({row})=>row.admission.eligible).map(({forecast})=>forecast)],now:new Date().toISOString()}) : empty('No offers published in this scope', 'No complete player contract with reviewed source permission matches this selection. Retained source observations are not admitted published offers. An admitted offer can display “price unavailable”; quotes, value estimates and tickets have separate checks.'), `${escape(scopeLabel())} · ${rows.length} published offers`, pill('Research only', 'research-pill')) + panel('Category evidence inventory', `<div class="table-wrap"><table class="inventory-table"><caption class="sr-only">Category-specific forecast, quote and settlement admission</caption><thead><tr><th scope="col">Category</th><th scope="col">Forecast</th><th scope="col">Quotes</th><th scope="col">Settlement</th></tr></thead><tbody>${categories.map(market => `<tr><th scope="row"><strong>${escape(market.code)}</strong><span class="cell-sub">${escape(market.name)}${market.requested ? '' : ' · optional'}</span></th><td>${pill('Unvalidated', 'neutral')}</td><td>${pill('Unverified', 'neutral')}</td><td>${pill('Unverified', 'neutral')}</td></tr>`).join('') || '<tr><td colspan="4">No inventory is available for this selection.</td></tr>'}</tbody></table></div>`, 'Each category retains its own status. Registry membership is not qualification.') + `<div class="notice"><strong>Independent evidence dimensions</strong><p>An observed offer, a research forecast, an evaluated model, a priced candidate and a settlement rule are separate states. No single badge substitutes for all five.</p></div>`;
}

function valueResearch() {
  return pageHeading('EXACT CONTRACTS, EXPLICIT ASSUMPTIONS', 'Value Research', 'A supported probability and an actual price are both required to estimate value.') + `<div class="two-col">${panel('Contract comparison', empty('No comparable priced contracts', 'No verified contemporaneous matching offers are published. An ESPN DraftKings label alone does not establish two-sided prices.', '⇄'))}${panel('Entry economics', empty('Payout terms not qualified', 'Sleeper side multipliers are not standalone sportsbook decimal odds. A complete entry needs actual payout and settlement terms.', '∑'))}</div>` + panel('What a value estimate must preserve', `<div class="requirements-grid">${[['Exact identity', 'League, player, event, stat, period, line, side, variant, venue and product.'], ['Probability source', 'Evaluated model, matching market reference or separately evaluated hybrid.'], ['Actual clocks', 'One observation for line and price; capture age and source update time or unknown.'], ['Settlement semantics', 'Pushes, voids, participation rules, guaranteed returns and any pool terms.']].map(([title, text]) => `<div><h3>${title}</h3><p>${text}</p></div>`).join('')}</div>`, 'Forecast accuracy and economic opportunity are evaluated separately.') + `<div class="notice"><strong>Value unavailable</strong><p>No live price, margin-removal reference, probability or provider payout is inferred from a missing field.</p></div>`;
}

function builder() {
  const universe = filterCandidateUniverse(allRows('candidates'), state.scope, supported(), state.builder.mode);
  return pageHeading('PROSPECTIVE PAPER RESEARCH', 'Paper Builder', 'Configure a 2–6-leg research request. A complete ticket must qualify on its own terms.', pill('NO_ACTION', 'warning-pill')) + `<div class="builder-layout"><section class="panel filter-panel"><h2 class="section-title">Define your paper request</h2>${scopeControl()}<fieldset class="leg-control"><legend>Requested legs</legend><div class="leg-choices">${[2, 3, 4, 5, 6].map(count => `<label><input type="radio" name="legs" value="${count}" ${state.builder.legs === count ? 'checked' : ''}><span>${count}</span></label>`).join('')}</div><p class="control-help">Six is preferred only when the complete ticket qualifies. Smaller tickets or NO_ACTION remain valid.</p></fieldset><fieldset class="mode-control"><legend>Direction policy</legend><div class="mode-choices">${[['OVER_ONLY', 'Over only'], ['UNDER_ONLY', 'Under only'], ['MIXED', 'Mixed']].map(([value, title]) => `<label><input type="radio" name="direction" value="${value}" ${state.builder.mode === value ? 'checked' : ''}><span>${title}</span></label>`).join('')}</div></fieldset><label class="filter-label venue-label">Eligible venue / product<select disabled aria-describedby="venue-help"><option>No admitted products</option></select></label><p id="venue-help" class="control-help">A ticket stays within one exact eligible venue, product and rules variant. Venue comparisons remain separate.</p><button type="button" class="button dark full-width" id="readiness">Check paper readiness <span aria-hidden="true">→</span></button><p class="control-help">This checks the published research state. It does not issue a ticket or create a prospective receipt.</p></section><div>${panel('Paper request', `<dl class="request-summary"><div><dt>Sport scope</dt><dd>${escape(scopeLabel())}</dd></div><div><dt>Requested size</dt><dd>${state.builder.legs} legs</dd></div><div><dt>Direction</dt><dd>${escape(state.builder.mode)}</dd></div><div><dt>Candidate universe</dt><dd>${universe.length} admitted candidates</dd></div><div><dt>Decision time</dt><dd>Not issued</dd></div><div><dt>Joint outcome method</dt><dd>Not qualified</dd></div><div><dt>Payout & settlement</dt><dd>Not verified</dd></div></dl><div class="decision-box" ${state.builder.checked ? 'role="status"' : ''}><span class="eyebrow">${state.builder.checked ? 'READINESS CHECK COMPLETE' : 'CURRENT PAPER STATE'}</span><strong>NO_ACTION</strong><p>No admitted candidates, complete product terms or qualified joint ticket calculation are published.</p></div>`, 'A request is not a frozen paper ticket.')}${panel('Qualification stays strict', `<ul class="plain-list"><li>A selected sport group never expands to fill legs.</li><li>All forecasts, quotes and terms precede one common decision time.</li><li>Initial suggested tickets require distinct players and events.</li><li>Independence, if used later, must be an explicit assumption.</li><li>No local draft is a durable prospective evidence ledger.</li></ul>`)}</div></div>`;
}

function gradeGroup(group) {
  const metadata = [['Evidence lane', group.evidence_lane], ['Model version', group.model_version], ['Full model commit', group.model_commit], ['Model code SHA-256', group.model_code_sha256], ['Conditioning', group.conditioning], ['Period', group.period], ['Overtime', group.extra_time_policy]];
  const summary = group.categories.length ? `<div class="table-wrap"><table class="grade-summary"><thead><tr><th scope="col">Category</th><th scope="col">Grade records</th><th scope="col">Mean CRPS / RPS</th><th scope="col">Log loss</th><th scope="col">Zero-support rows</th><th scope="col">Brier</th></tr></thead><tbody>${group.categories.map(category => `<tr><th scope="row">${escape(category.code)}</th><td>${category.grade_count}</td><td>${number(category.mean_crps)}</td><td>${category.zero_support_count ? '∞ · zero support' : number(category.mean_log_loss)}</td><td>${category.zero_support_count}</td><td>${category.mean_brier === null ? 'Not a binary target' : number(category.mean_brier)}</td></tr>`).join('')}</tbody></table></div>` : empty('No scored category outcomes in this group', 'DNP and unresolved grade records have no statistical scores and do not enter the means.');
  return `<section class="panel grade-group" data-evidence-lane="${escape(group.evidence_lane)}" data-model-commit="${escape(group.model_commit)}" data-model-code="${escape(group.model_code_sha256)}"><div class="panel-heading"><h3>${escape(group.league)} · ${group.evidence_lane === 'RECONSTRUCTED_RESEARCH' ? 'Reconstructed research' : 'Captured forecasts'}</h3>${pill('Research only', 'neutral')}</div><p>${group.grade_count} grade records · ${group.scored_count} scored · ${group.dnp_count} DNP · ${group.unresolved_count} unresolved</p><dl class="forecast-provenance">${metadata.map(([label, value]) => `<div><dt>${label}</dt><dd><code>${escape(value)}</code></dd></div>`).join('')}</dl>${summary}</section>`;
}

function performance() {
  const grades = scopedRows('performance'), scored = grades.filter(grade => grade.status === 'SCORED');
  const groups = groupForecastGrades(grades, scopedRows('forecasts'));
  const pending = scopedRows('forecasts').filter(forecast => forecastGradeState(forecast, grades).pending).length;
  const gradeSummary = groups.length ? `<div class="notice"><strong>Descriptive forecast diagnostics</strong><p>Each evidence lane and exact model revision has a separate summary. Grade records are not independent trials or a confirmatory evaluation. Scores retain category-specific units; no cross-category accuracy number is produced.</p></div>${groups.map(gradeGroup).join('')}` : empty('No typed forecast grades published', 'Forecast scoring is separate from wager or ticket settlement. No missing grade is converted into a win, loss or zero outcome.');
  const identities = grades.length ? `<ul class="performance-targets" aria-label="Published statistical forecast grades">${grades.map(grade=>{const f=allRows('forecasts').find(row=>row.forecast_id===grade.forecast_id),d=displayTarget(f,state.snapshot?.display);return `<li><div><strong>${escape(d.playerName)}</strong><span>${escape(d.matchup)} · ${datetime(f.event_starts_at)}</span><span>${escape(d.teamName)} · opponent ${escape(d.opponentName)}</span></div>${pill(grade.status.replaceAll('_',' '),'neutral')}</li>`;}).join('')}</ul>` : '';
  const receipts = grades.length ? `<details class="grade-receipts"><summary>Inspect ${grades.length} forecast grade receipts</summary>${grades.map(grade => {const forecast = allRows('forecasts').find(row => row.forecast_id === grade.forecast_id), display=displayTarget(forecast,state.snapshot?.display); return `<article class="grade-receipt"><div class="source-card-heading"><h3>${escape(display.playerName)}</h3>${pill(grade.status.replaceAll('_', ' '), 'neutral')}</div><p class="forecast-context">${escape(display.matchup)} · ${datetime(forecast.event_starts_at)}<br>${escape(display.teamName)} · opponent ${escape(display.opponentName)}</p><p>${escape(grade.evidence_lane)} · Model ${escape(forecast.model_version)} · Commit <code class="break-code">${escape(forecast.model_commit)}</code><br>Graded ${datetime(grade.graded_at)} · Financial settlement: NOT_EVALUATED. Scores shown to five significant digits; exact score text remains in the cell title.</p><p class="receipt-id">Grade <code>${escape(grade.grade_id)}</code><br>Forecast <code>${escape(grade.forecast_id)}</code><br>Outcome <code>${escape(grade.outcome_id)}</code></p>${grade.status === 'SCORED' ? `<div class="table-wrap"><table><thead><tr><th scope="col">Category</th><th scope="col">Observed</th><th scope="col">CRPS / RPS</th><th scope="col">Log loss</th></tr></thead><tbody>${grade.categories.map(category => `<tr><th scope="row">${escape(category.code)}</th><td>${category.observed}</td><td title="${escape(category.crps)}">${number(category.crps)}</td><td title="${escape(category.log_loss_status === 'ZERO_SUPPORT' ? 'Infinite loss' : category.log_loss)}">${category.log_loss_status === 'ZERO_SUPPORT' ? '∞ · ZERO_SUPPORT' : number(category.log_loss)}</td></tr>`).join('')}</tbody></table></div>` : '<p>No category score is assigned. DNP and unresolved outcomes remain separate states.</p>'}</article>`;}).join('')}</details>` : '';
  return pageHeading('EVIDENCE, KEPT SEPARATE', 'Performance', 'Software behavior, forecast grades and future paper outcomes answer different questions.') + `<div class="scorecard-grid">${[['01', 'Forecast research', `${grades.length} typed grade records published`, 'Descriptive category scores do not establish model validation.'], ['02', 'Selected-leg outcomes', 'No prospective leg results published', 'Frozen candidate universes and genuine decision clocks before events occur.'], ['03', 'Complete tickets', 'No settled paper tickets published', 'Actual product payouts, full and partial returns, voids, paper ROI and exposure.']].map(([number, title, status, text]) => `<section class="panel scorecard"><span class="scorecard-number">${number}</span><h2>${title}</h2><div class="scorecard-value">—</div><strong>${status}</strong><p>${text}</p></section>`).join('')}</div>` + panel('Forecast grades', identities + gradeSummary + receipts, `${escape(scopeLabel())} · ${scored.length} scored grade records · ${grades.length - scored.length} DNP or unresolved · ${pending} forecast records pending a verified grade. Summaries retain evidence lane and model identity; financial settlement is not evaluated.`) + dailyPanel(true) + pairedPanel(true) + reservedPanel(true) + panel('Evidence lanes', `<div class="table-wrap"><table><thead><tr><th scope="col">Lane</th><th scope="col">What it can establish</th></tr></thead><tbody>${[['SYNTHETIC_TEST', 'Specified software behavior on invented examples.'], ['RECONSTRUCTED_RESEARCH', 'Historical research; original pregame availability is not implied.'], ['VERIFIED_ASOF_REPLAY', 'Archived inputs independently verified at the historical cutoff.'], ['REAL_TIME_CAPTURED', 'Actual future information captured before the declared decision deadline.']].map(([lane, text]) => `<tr><th scope="row"><code>${lane}</code></th><td>${text}</td></tr>`).join('')}</tbody></table></div>`, 'A successful unit test is not model performance. A future outcome cannot be created ahead of its event.') + `<div class="notice"><strong>Product qualification remains unavailable</strong><p>No hit rate, ROI, calibrated accuracy label or completed model claim follows from these research records. Financial settlement remains NOT_EVALUATED.</p></div>`;
}

function sources() {
  const sources = sports().flatMap(sport => sport.sources.map(source => ({...source, league: sport.league})));
  const displaySources = state.snapshot?.display?.catalog.sources || [];
  const displayEvidence = panel('Historical display-name verification', displaySources.length ? `<p>Catalog verified ${datetime(state.snapshot.display.catalog.verified_at)}. Names and historical matchups only; these post-event observations never become forecast inputs.</p><ul class="performance-targets">${displaySources.map(source=>`<li><div><strong>Archived event ${escape(source.event_id)}</strong><span>Observed ${datetime(source.observed_at)} · Source update time: ${source.source_updated_at ? datetime(source.source_updated_at) : 'unknown'}</span><span>${source.facts.players.length} verified player labels · ${source.facts.teams.map(t=>escape(t.display_name)).join(' / ')}</span></div></li>`).join('')}</ul>` : '<p>Display metadata unavailable. Original source IDs remain visible; no name or historical team is guessed. This does not remove valid forecast distributions.</p>');
  return pageHeading('COVERAGE & PROVENANCE', 'Source Health', 'Actual access evidence and category coverage determine what the lab can publish.') + researchStatus(sports()) + displayEvidence + panel('Retained source audit observations', sources.length ? `<div class="source-list">${sources.map(source => `<article class="source-card"><div class="source-symbol" aria-hidden="true">◎</div><div><div class="source-card-heading"><h3>${escape(source.name)}</h3>${pill(source.status.replaceAll('_', ' '), 'neutral')}</div><p>${escape(source.detail)}</p><div class="source-meta">${escape(source.league)} <span>·</span> Retained audit observation: ${datetime(source.observed_at)}</div></div></article>`).join('')}</div>` : empty('Source evidence unavailable', 'No source-status snapshot has loaded. This is not evidence of a valid empty upstream board.'), 'These dated initial source audits are not current feeds. Forecast-input preparation and display verification have separate clocks; a failed request and a verified empty board are different states.') + `<div class="two-col">${panel('Snapshot provenance', `<dl class="request-summary"><div><dt>Publication</dt><dd>${datetime(state.snapshot?.manifest.published_at)}</dd></div><div><dt>Build commit</dt><dd><code class="break-code">${escape(state.snapshot?.manifest.build_commit || 'Unavailable')}</code></dd></div><div><dt>Snapshot ID</dt><dd><code class="break-code">${escape(state.snapshot?.manifest.snapshot_id || 'Unavailable')}</code></dd></div><div><dt>Integrity</dt><dd>${sports().length ? 'Loaded sport bytes matched manifest SHA-256' : 'No sport snapshot verified'}</dd></div></dl><p class="control-help">Hashes detect changed content; they do not prove upstream authenticity, permission or original publication time.</p>`)}${panel('Boundaries of this publication', `<ul class="plain-list"><li>No new paid services, signups or API keys.</li><li>Public URL access does not establish collection or redistribution permission.</li><li>No upstream scraping or model rebuilding runs in your browser.</li><li>Unknown source update clocks stay unknown.</li><li>Raw archives and private inputs are excluded from site assets.</li></ul><a class="text-link" href="https://github.com/NickNicky19/Nicks-multisport-lab-project/blob/main/docs/OFFER_PUBLICATION_READINESS.md">Offer evidence and publication gates <span aria-hidden="true">→</span></a>`)}</div>`;
}

function specials() {
  return pageHeading('JOINT OUTCOMES & THRESHOLDS', 'Specials', 'Double-doubles and triple-doubles remain in the full NBA research scope.') + `<div class="two-col">${panel('Double-double · DD', `<div class="special-number">2<span>or more categories at ten</span></div><p class="body-copy">Count PTS, REB, AST, STL and BLK reaching at least ten in the same outcome sample.</p>${pill('Forecast unvalidated', 'neutral')}`)}${panel('Triple-double · TD', `<div class="special-number">3<span>or more categories at ten</span></div><p class="body-copy">Use the same five categories and the same joint outcome sample. Every triple-double also satisfies a double-double.</p>${pill('Forecast unvalidated', 'neutral')}`)}</div>` + panel('Separately qualified Specials', empty('No supported Specials offers', 'Category definitions do not establish observed product availability, calibrated probabilities or exact venue settlement rules.', '✧')) + `<div class="notice"><strong>Coherence before qualification</strong><p>Scoring, combinations, DD and TD share outcomes. Derived identities preserve TD ≤ DD; each category still needs its own evaluation. Turnovers and three-point makes do not count as extra DD/TD categories.</p></div>`;
}

function bindControls() {
  document.querySelectorAll('[data-scope]').forEach(button => button.addEventListener('click', () => {
    const mode = button.dataset.scope;
    const existing = resolveSportScope(state.scope, supported());
    state.scope = {mode, sports: mode === 'ALL' ? [] : mode === 'SINGLE' ? existing.slice(0, 1).length ? existing.slice(0, 1) : supported().slice(0, 1) : existing};
    state.filters.category = 'ALL'; state.visiblePros004 = 28; state.visiblePaired = 28; state.visibleDaily = 28; state.builder.checked = false; render();
  }));
  document.querySelectorAll('input[name="sport"]').forEach(input => input.addEventListener('change', () => {
    const checked = [...document.querySelectorAll('input[name="sport"]:checked')].map(element => element.value);
    state.scope.sports = checked; state.filters.category = 'ALL'; state.visiblePros004 = 28; state.visiblePaired = 28; state.visibleDaily = 28; state.builder.checked = false; render();
  }));
  document.querySelectorAll('[data-filter]').forEach(input => input.addEventListener('change', () => {state.filters[input.dataset.filter] = input.value; state.visibleForecasts = 28; state.visiblePros004 = 28; state.visiblePaired = 28; state.visibleDaily = 28; if(input.dataset.filter==='view')location.hash=input.value==='history'?'#/props/history':'#/props/upcoming'; render();}));
  document.querySelector('#more-pros004')?.addEventListener('click', () => {state.visiblePros004 += 28; render();});
  document.querySelector('#more-sdv-daily')?.addEventListener('click', () => {state.visibleDaily += 28; render();});
  document.querySelector('#more-paired-research')?.addEventListener('click', () => {state.visiblePaired += 28; render();});
  document.querySelector('#more-forecasts')?.addEventListener('click', () => {state.visibleForecasts += 28; render();});
  document.querySelector('#view-history')?.addEventListener('click', () => {state.filters.view = 'history'; state.visibleForecasts = 28; render();});
  document.querySelectorAll('input[name="legs"]').forEach(input => input.addEventListener('change', () => {const count = Number(input.value); if (validRequestedLegCount(count)) state.builder.legs = count; state.builder.checked = false; render();}));
  document.querySelectorAll('input[name="direction"]').forEach(input => input.addEventListener('change', () => {state.builder.mode = input.value; state.builder.checked = false; render();}));
  document.querySelector('#readiness')?.addEventListener('click', () => {state.builder.checked = true; render(); document.querySelector('.decision-box').focus?.();});
}

function render() {
  const requested = location.hash.slice(2) || 'overview';
  const routeKey = ['props/history','props/upcoming'].includes(requested) ? 'props' : requested;
  const route = routes.find(([key]) => key === routeKey);
  const key = route?.[0] || 'unknown';
  document.querySelector('#navigation').innerHTML = routes.map(([id, label, icon]) => `<a href="#/${id}" class="nav-item ${id === key ? 'active' : ''}" ${id === key ? 'aria-current="page"' : ''}><span aria-hidden="true">${icon}</span>${label}${id === 'specials' ? '<span class="nav-small">DD / TD</span>' : ''}</a>`).join('');
  document.querySelector('#breadcrumb').textContent = `The lab / ${route?.[1] || 'Page unavailable'}`;
  document.title = `${route?.[1] || 'Page unavailable'} · Nick’s Multisport Lab`;
  const views = {overview, props, value: valueResearch, builder, performance, sources, specials};
  main.innerHTML = publicationStatus() + (views[key] ? views[key]() : pageHeading('PAGE UNAVAILABLE', 'This route is not in the lab.', 'Use the navigation to return to a published research view.') + '<a class="button dark" href="#/overview">Back to overview</a>') + snapshotNote();
  bindControls();
}

window.addEventListener('hashchange', () => {
  if (location.hash === '#main') {main.focus(); return;}
  if (location.hash === '#/props/history') state.filters.view='history';
  if (location.hash === '#/props/upcoming') state.filters.view='upcoming';
  render(); main.focus(); window.scrollTo(0, 0);
});

try {state.snapshot = await loadSnapshot();} catch (error) {state.error = error.message || 'The publication could not be verified.';}
render();
